import base64
import service_pb2 as pb2

# The string from your browser console
base64_string =""
raw = base64.b64decode(base64_string, validate=True)
world = pb2.WorldModel()
world.ParseFromString(raw)

print(f"Cycle: {world.cycle}")
print(f"Our Team Score ({world.our_team_name}): {world.our_team_score}")
print(f"Their Team Score ({world.their_team_name}): {world.their_team_score}")
print(f"Left Team Score: {world.left_team_score}")
print(f"Right Team Score: {world.right_team_score}")